import os, json

class FileCache:
    def get(self, key):
        path = f"/tmp/cache/{key}.json"
        if os.path.exists(path):
            with open(path) as f:
                return json.load(f)
        return None

    def set(self, key, value):
        path = f"/tmp/cache/{key}.json"
        if not os.path.exists(path):
            with open(path, 'w') as f:
                json.dump(value, f)
